macro_rules! deps {
    () => {
        PrivateUninhabitedField!();
        Constructor!();
        ConstructorSet!();
        DeconstructedPat!();
        IntRange!();
    };
}

macro_rules! PatCx {
    () => {
        deps!();
        # [doc = " Context that provides type information about constructors."] # [doc = ""] # [doc = " Most of the crate is parameterized on a type that implements this trait."] pub trait PatCx : Sized + fmt :: Debug { # [doc = " The type of a pattern."] type Ty : Clone + fmt :: Debug ; # [doc = " Errors that can abort analysis."] type Error : fmt :: Debug ; # [doc = " The index of an enum variant."] type VariantIdx : Clone + Idx + fmt :: Debug ; # [doc = " A string literal"] type StrLit : Clone + PartialEq + fmt :: Debug ; # [doc = " Extra data to store in a match arm."] type ArmData : Copy + Clone + fmt :: Debug ; # [doc = " Extra data to store in a pattern."] type PatData : Clone ; fn is_exhaustive_patterns_feature_on (& self) -> bool ; # [doc = " Whether to ensure the non-exhaustiveness witnesses we report for a complete set. This is"] # [doc = " `false` by default to avoid some exponential blowup cases such as"] # [doc = " <https://github.com/rust-lang/rust/issues/118437>."] fn exhaustive_witnesses (& self) -> bool { false } # [doc = " The number of fields for this constructor."] fn ctor_arity (& self , ctor : & Constructor < Self > , ty : & Self :: Ty) -> usize ; # [doc = " The types of the fields for this constructor. The result must contain `ctor_arity()` fields."] fn ctor_sub_tys (& self , ctor : & Constructor < Self > , ty : & Self :: Ty ,) -> impl Iterator < Item = (Self :: Ty , PrivateUninhabitedField) > + ExactSizeIterator ; # [doc = " The set of all the constructors for `ty`."] # [doc = ""] # [doc = " This must follow the invariants of `ConstructorSet`"] fn ctors_for_ty (& self , ty : & Self :: Ty) -> Result < ConstructorSet < Self > , Self :: Error > ; # [doc = " Write the name of the variant represented by `pat`. Used for the best-effort `Debug` impl of"] # [doc = " `DeconstructedPat`. Only invoqued when `pat.ctor()` is `Struct | Variant(_) | UnionField`."] fn write_variant_name (f : & mut fmt :: Formatter < '_ > , ctor : & crate :: constructor :: Constructor < Self > , ty : & Self :: Ty ,) -> fmt :: Result ; # [doc = " Raise a bug."] fn bug (& self , fmt : fmt :: Arguments < '_ >) -> Self :: Error ; # [doc = " Lint that the range `pat` overlapped with all the ranges in `overlaps_with`, where the range"] # [doc = " they overlapped over is `overlaps_on`. We only detect singleton overlaps."] # [doc = " The default implementation does nothing."] fn lint_overlapping_range_endpoints (& self , _pat : & DeconstructedPat < Self > , _overlaps_on : IntRange , _overlaps_with : & [& DeconstructedPat < Self >] ,) { } # [doc = " The maximum pattern complexity limit was reached."] fn complexity_exceeded (& self) -> Result < () , Self :: Error > ; # [doc = " Lint that there is a gap `gap` between `pat` and all of `gapped_with` such that the gap is"] # [doc = " not matched by another range. If `gapped_with` is empty, then `gap` is `T::MAX`. We only"] # [doc = " detect singleton gaps."] # [doc = " The default implementation does nothing."] fn lint_non_contiguous_range_endpoints (& self , _pat : & DeconstructedPat < Self > , _gap : IntRange , _gapped_with : & [& DeconstructedPat < Self >] ,) { } # [doc = " Check if we may need to perform additional deref-pattern-specific validation."] fn match_may_contain_deref_pats (& self) -> bool { true } # [doc = " The current implementation of deref patterns requires that they can't match on the same"] # [doc = " place as a normal constructor. Since this isn't caught by type-checking, we check it in the"] # [doc = " `PatCx` before running the analysis. This reports an error if the check fails."] fn report_mixed_deref_pat_ctors (& self , deref_pat : & DeconstructedPat < Self > , normal_pat : & DeconstructedPat < Self > ,) -> Self :: Error ; }
    };
}

PatCx!();